[CmdletBinding()]param([string]$BaseUrl='https://tboxapp.top')
$ErrorActionPreference='Stop'; $pages=@('index.html','download.html','faq.html','pricing.html','activate.html','buy.html','membership.html','setup-key.html','404.html'); $fail=0; foreach($p in $pages){try{$u="$($BaseUrl.TrimEnd('/'))/${p}?cb=$([DateTimeOffset]::UtcNow.ToUnixTimeMilliseconds())";$r=Invoke-WebRequest -UseBasicParsing -Uri $u -TimeoutSec 30 -Headers @{'Cache-Control'='no-cache'};$t=[Text.Encoding]::UTF8.GetString($r.RawContentStream.ToArray());$img=[regex]::Match($t,'<meta\s+property="og:image"\s+content="([^"]+)"').Groups[1].Value;$can=[regex]::Match($t,'<link\s+rel="canonical"\s+href="([^"]+)"').Groups[1].Value;$ok=($r.StatusCode -eq 200 -and $img -eq 'https://tboxapp.top/assets/img/og-wechat.png' -and $can.StartsWith('https://tboxapp.top'));if(-not $ok){$fail++};"$p PASS=$ok HTTP=$($r.StatusCode) og:image=$img canonical=$can"}catch{$fail++;"$p PASS=False ERROR=$($_.Exception.Message)"}}; if($fail){"SITE FAIL pages=$($pages.Count) failed=$fail";exit 1}else{"SITE PASS pages=$($pages.Count)";exit 0}


